var THREE4 = _THREE();

class SparkleParticle {
  scene;
  position;
  texture;
  duration;
  particleCount;
  timeElapsed;
  geometry;
  material;
  particles;
  constructor(scene, position, texture, duration = 0.2, particleCount = 6) {
    this.scene = scene;
    this.position = position;
    this.texture = texture;
    this.duration = duration;
    this.particleCount = particleCount;
    this.timeElapsed = 0;
    this.initParticles();
  }
  initParticles() {
    this.geometry = new THREE4.BufferGeometry;
    const positions = [];
    const sizes = [];
    const minDistance = 1;
    for (let i = 0;i < this.particleCount; i++) {
      let validPosition = false;
      let x, y, z;
      while (!validPosition) {
        x = this.position.x + Math.random() * 5 - 2.5;
        y = this.position.y + Math.random() * 6.5 - 2.5;
        z = this.position.z + Math.random() * 5 - 2.5;
        validPosition = true;
        for (let j = 0;j < i; j++) {
          const dx = x - positions[j * 3];
          const dy = y - positions[j * 3 + 1];
          const dz = z - positions[j * 3 + 2];
          const distance = Math.sqrt(dx * dx + dy * dy + dz * dz);
          if (distance < minDistance) {
            validPosition = false;
            break;
          }
        }
      }
      positions.push(x, y, z);
      sizes.push(Math.random() * 5 + 0.1);
    }
    this.geometry.setAttribute("position", new THREE4.Float32BufferAttribute(positions, 3));
    this.geometry.setAttribute("size", new THREE4.Float32BufferAttribute(sizes, 1));
    this.material = new THREE4.PointsMaterial({
      size: 4,
      map: this.texture,
      transparent: true,
      blending: THREE4.AdditiveBlending,
      depthWrite: false
    });
    this.particles = new THREE4.Points(this.geometry, this.material);
    this.scene.add(this.particles);
  }
  update(deltaTime) {
    this.timeElapsed += deltaTime;
    this.material.opacity = 1 - this.timeElapsed / this.duration;
    if (this.timeElapsed >= this.duration) {
      this.dispose();
    }
    return true;
  }
  dispose() {
    this.scene.remove(this.particles);
    this.particles.geometry.dispose();
    this.particles.material.dispose();
    return false;
  }
}

