      const posStart = new THREE13.Vector3(0, 65, 550);
      const atStart = new THREE13.Vector3(0, 65, 0);
      const posEnd = new THREE13.Vector3(0, 75, 850);
      const atEnd = new THREE13.Vector3(0, 88, 0);
      const t = (miiHeight - 0.5) / (1.264 - 0.5);
